INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('39047abc-687a-4ad8-91f5-f383049ef091', 'a1b2c3d4-1111-4000-8000-000000000001', 6, 'Perseverança na Rotina', 'Quando a motivação acaba, a disciplina começa', '{"intro": "A maior tenta\u00e7\u00e3o da vida espiritual n\u00e3o \u00e9 o pecado grave \u2014 \u00e9 a mediocridade. \u00c9 o dia em que voc\u00ea \"n\u00e3o est\u00e1 com vontade\". Santa Teresa de \u00c1vila confessou que, por anos, sua ora\u00e7\u00e3o era \u00e1rida e sem consola\u00e7\u00e3o. Mas ela perseverou. E foi nos desertos que encontrou as maiores gra\u00e7as. A rotina espiritual n\u00e3o depende de sentir \u2014 depende de decidir, todos os dias.", "prayer": "Senhor, quando a aridez vier, lembra-me que Tu est\u00e1s presente mesmo no sil\u00eancio. D\u00e1-me a gra\u00e7a da perseveran\u00e7a. Am\u00e9m.", "practice": "Escreva sua Regra de Vida pessoal: hor\u00e1rio de ora\u00e7\u00e3o, leitura b\u00edblica, exame de consci\u00eancia. Cole em um lugar vis\u00edvel. Comprometa-se por 21 dias.", "scripture": "\"Aquele que perseverar at\u00e9 o fim, esse ser\u00e1 salvo.\" \u2014 Mt 24,13", "reflection": "Qual \u00e9 sua maior dificuldade para manter uma rotina espiritual? O que te faria n\u00e3o desistir mesmo nos dias dif\u00edceis?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;